mapper.select:
SELECT
c.*,
u.user_real_name as teacherName  FROM course_table c
LEFT JOIN user_table u ON c.teacher_id = u.user_id


        AND c.course_name LIKE concat('%', #{courseName}, '%')


        AND c.teacher_id = #{teacherId}


        AND c.course_status = #{courseStatus}


        AND c.course_time = #{courseTime}


        AND c.course_room LIKE concat('%', #{courseRoom}, '%')


ORDER BY c.course_createtime DESC

mapper.update:
UPDATE course_table
course_name = #{courseName}, course_credit = #{courseCredit}, max_num = #{maxNum}, course_status = #{courseStatus}, course_time = #{courseTime}, course_room = #{courseRoom}, selected_num = #{selectedNum},
WHERE course_id = #{courseId}
